      <Tabs value={value} onChange={(_, v) => setValue(v)}>
        <Tab label="Historial de acciones" />
        <Tab label="Stock" />
        <Tab label="Historial de retiros" />
      </Tabs>

      <TabPanel value={value} index={0}>
        <Acciones />
      </TabPanel>

      <TabPanel value={value} index={1}>
        <Stock />
      </TabPanel>
      <TabPanel value={value} index={2}>
        <Retiros />
      </TabPanel>
    </Box>
  );
};

export default Reportes;

import React, { useEffect, useState, useMemo } from "react";
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Typography,
  TextField,
  Box,
  Button,
  TablePagination,
  InputLabel,
  Select,
  MenuItem
} from "@mui/material";
import { useDispatch, useSelector } from "react-redux";
import { getHistorialRetiros } from "../../../../../../redux/actions/stockAction";
import ExcelJS from 'exceljs';
import { saveAs } from 'file-saver';
import dayjs from 'dayjs';
import DownloadIcon from '@mui/icons-material/Download';



const Retiros = () => {
  const dispatch = useDispatch();

  useEffect(() => {
    dispatch(getHistorialRetiros());
  }, [dispatch]);

  const reportes = useSelector(state => state.stock.items);

  // ---- STATES FILTROS ----
  const [busqueda, setBusqueda] = useState("");
  const [desde, setDesde] = useState("");
  const [hasta, setHasta] = useState("");
  const [terciarizado, setTerciarizado] = useState("");
 const [deposito, setDeposito] = useState("");
  // ---- PAGINADO ----
  const [page, setPage] = useState(0);
  const rowsPerPage = 20;

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  // ---- LIMPIAR FILTROS ----
  const limpiarFiltros = () => {
    setBusqueda("");
    setDesde("");
    setHasta("");
    setTerciarizado("");
     setDeposito("");
  };

  // ---- FILTRO INTELIGENTE ----
  const historialFiltrado = useMemo(() => {
    if (!reportes) return [];

    return reportes.filter(r => {
      const texto = busqueda.toLowerCase();

      const coincideTexto =
        r.categoria?.toLowerCase().includes(texto) ||
        r.descripcion?.toLowerCase().includes(texto) ||
        r.quienRetira?.toLowerCase().includes(texto) ||
        r.deposito?.toLowerCase().includes(texto);

      const fechaReporte = new Date(r.fecha);

      const coincideDesde = desde
        ? fechaReporte >= new Date(desde + "T00:00:00")
        : true;

      const coincideHasta = hasta
        ? fechaReporte <= new Date(hasta + "T23:59:59")
        : true;

      const coincideterciarizado =
  terciarizado === "" ? true : r.terciarizado === terciarizado;

  const coincidedeposito =
  deposito === "" ? true : r.deposito === deposito;


      return coincideTexto && coincideDesde && coincideHasta && coincideterciarizado && coincidedeposito;
    });
  }, [reportes, busqueda, desde, hasta, terciarizado, deposito]);

  // ---- RESET PAGINA SI CAMBIA FILTRO ----
  useEffect(() => {
    setPage(0);
  }, [busqueda, desde, hasta]);

  // ---- SLICE PAGINADO ----
  const historialPaginados = historialFiltrado.slice(
    page * rowsPerPage,
    page * rowsPerPage + rowsPerPage
  );

  const exportarAExcel = async () => {
  const workbook = new ExcelJS.Workbook();
  const worksheet = workbook.addWorksheet('Historial de Retiros');

  // Columnas
  worksheet.columns = [
    { header: 'Responsable', key: 'quienRetira', width: 25 },
    { header: 'Categoría', key: 'categoria', width: 20 },
    { header: 'Descripción', key: 'descripcion', width: 30 },
    { header: 'Deposito', key: 'deposito', width: 30 },
    { header: 'Acción / Cantidad', key: 'accion', width: 20 },
    { header: 'Terciarizado', key: 'terciarizado', width: 15 },
    { header: 'Fecha', key: 'fecha', width: 20 },
  ];

  // Estilo de encabezado
  worksheet.getRow(1).eachCell((cell) => {
    cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
    cell.fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: 'FF12824C' },
    };
    cell.alignment = { vertical: 'middle', horizontal: 'center' };
    cell.border = {
      top: { style: 'thin' },
      left: { style: 'thin' },
      bottom: { style: 'thin' },
      right: { style: 'thin' },
    };
  });

  // Datos filtrados
  historialFiltrado.forEach((r) => {
    worksheet.addRow({
      quienRetira: r.quienRetira,
      categoria: r.categoria,
      descripcion: r.descripcion,
      deposito: r.deposito,
      accion: `${r.accion} / cant:${r.enStock || ''}`,
      terciarizado: r.terciarizado ? 'Si' : 'No',
      fecha: new Date(r.fecha).toLocaleString(),
    });
  });




  // Estilo de celdas
  worksheet.eachRow({ includeEmpty: false }, (row, rowNumber) => {
    if (rowNumber === 1) return; // encabezado
    row.eachCell((cell) => {
      cell.alignment = { vertical: 'middle', horizontal: 'center' };
      cell.border = {
        top: { style: 'thin' },
        left: { style: 'thin' },
        bottom: { style: 'thin' },
        right: { style: 'thin' },
      };
    });
  });

  const buffer = await workbook.xlsx.writeBuffer();
  const blob = new Blob([buffer], {
    type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  });

  saveAs(blob, `Historial Retiros ${dayjs().format('DD-MM-YYYY')}.xlsx`);
};

  const totales = useMemo(() => {
  let totalAgregadoNuevo = 0;   // "Agregado"
  let totalAgregadoStock = 0;   // "Agregado Stock"
  let totalRetirado = 0;        // "Retiro Stock"

  historialFiltrado.forEach(r => {
    const cantidad = Number(r.enStock) || 0;

    if (r.accion === "Agregado") {
      totalAgregadoNuevo += cantidad;
    }

    if (r.accion === "Agregado Stock") {
      totalAgregadoStock += cantidad;
    }

    if (r.accion === "Retiro Stock") {
      totalRetirado += cantidad;
    }
  });

  return {
    totalAgregadoNuevo,
    totalAgregadoStock,
    totalRetirado
  };
}, [historialFiltrado]);


  return (
    <TableContainer component={Paper}>
      <Typography sx={{ p: 2, fontFamily: "interTight" }} variant="h6">
        Historial de Retiros
      </Typography>

      {/* ---- FILTROS ---- */}
      <Box sx={{ display: "flex", gap: 2, p: 2, flexWrap: "wrap", alignItems: "center" }}>

        <TextField
          label="Buscar..."
          variant="outlined"
          size="small"
          value={busqueda}
          onChange={(e) => setBusqueda(e.target.value)}
        />

        <TextField
          label="Desde"
          type="date"
          size="small"
          InputLabelProps={{ shrink: true }}
          value={desde}
          onChange={(e) => setDesde(e.target.value)}
        />

        <TextField
          label="Hasta"
          type="date"
          size="small"
          InputLabelProps={{ shrink: true }}
          value={hasta}
          onChange={(e) => setHasta(e.target.value)}
        />

    <Box>


       <InputLabel id="terciarizado-label">Terciarizado</InputLabel>
        <Select
          labelId="terciarizado-label"
          value={terciarizado}
          label="Terciarizado"
          size="small"
          onChange={(e) => setTerciarizado(e.target.value)}
          sx={{ minWidth: 140 }}
        >
          <MenuItem value="">Todos</MenuItem>
          <MenuItem value={true}>Si</MenuItem>
          <MenuItem value={false}>No</MenuItem>
        </Select>
        </Box>

         <Box>
 <InputLabel id="terciarizado-label">Deposito</InputLabel>
        <Select
          labelId="deposito-label"
          value={deposito}
          label="Deposito"
          size="small"
          onChange={(e) => setDeposito(e.target.value)}
          sx={{ minWidth: 140 }}
        >
          <MenuItem value="">Todos</MenuItem>
          <MenuItem value={"General"}>General</MenuItem>
          <MenuItem value={"Nave"}>Nave</MenuItem>
          <MenuItem value={"Oficina"}>Oficina</MenuItem>
        </Select>
         </Box>



        <Button
          variant="outlined"
          color="success"
          startIcon={<DownloadIcon />}
          onClick={exportarAExcel}
        >
          Exportar Excel
        </Button>



        <Button
          variant="outlined"

          size="small"
          onClick={limpiarFiltros}
        >
          Limpiar
        </Button>
      </Box>
      <Box sx={{ display: "flex", gap: 4, px: 2, pb: 2, flexWrap: "wrap" }}>
        <Typography variant="subtitle2" color="green">
          Ingreso Item Nuevo: {totales.totalAgregadoNuevo}
        </Typography>

        <Typography variant="subtitle2" color="blue">
          Agregado a Stock: {totales.totalAgregadoStock}
        </Typography>

        <Typography variant="subtitle2" color="red">
          Retirado: {totales.totalRetirado}
        </Typography>
      </Box>


      <Table>
        <TableHead>
          <TableRow>
            <TableCell>Responsable</TableCell>
            <TableCell>Categoria</TableCell>
            <TableCell>Descripcion</TableCell>
            <TableCell>Deposito</TableCell>
            <TableCell>Acción</TableCell>
            <TableCell>Terciarizado</TableCell>
            <TableCell>Fecha</TableCell>
          </TableRow>
        </TableHead>

        <TableBody>
          {historialPaginados.map((a) => (

            <TableRow key={a._id}>
              <TableCell>{a.quienRetira}</TableCell>
              <TableCell>{a.categoria}</TableCell>
              <TableCell>{a.descripcion}</TableCell>
               <TableCell>{a.deposito}</TableCell>
              <TableCell>{a.accion}</TableCell>
              <TableCell>{a.terciarizado ? 'Si': 'No'}</TableCell>
              <TableCell>
                {new Date(a.fecha).toLocaleString()}
              </TableCell>
            </TableRow>
          ))}

          {historialFiltrado.length === 0 && (
            <TableRow>
              <TableCell colSpan={4} align="center">
                No hay historial
              </TableCell>
            </TableRow>
          )}
        </TableBody>
      </Table>

      {/* ---- PAGINADO ---- */}
      <TablePagination
        component="div"
        count={historialFiltrado.length}
        page={page}
        onPageChange={handleChangePage}
        rowsPerPage={rowsPerPage}
        rowsPerPageOptions={[20]}
        labelRowsPerPage="Filas por página"
      />
    </TableContainer>
  );
};

export default Retiros;

import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  Paper,
  TextField,
  Button,
  IconButton,
  CircularProgress,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  MenuItem,
  Select,
  FormControl,
  InputLabel,
  TableRow
} from '@mui/material';
import Collapse from '@mui/material/Collapse';
import KeyboardArrowDownIcon from '@mui/icons-material/KeyboardArrowDown';
import KeyboardArrowUpIcon from '@mui/icons-material/KeyboardArrowUp';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import AddIcon from '@mui/icons-material/Add';
import { useDispatch, useSelector } from 'react-redux';
import { getStock, putStock, deleteStock, postStock, getStockConfig } from '../../../../../../redux/actions/stockAction';


export default function GestionInventario() {
  const dispatch = useDispatch();

  // Traemos los items de stock y la configuración del back
  const { items, loading } = useSelector((state) => state.stock);
  const { config } = useSelector((state) => state.configStock);

  const [openRows, setOpenRows] = useState({});
  const [open, setOpen] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [search, setSearch] = useState("");
  const [formData, setFormData] = useState({
    id: '',
    categoria: '',
    descripcion: '',
    enStock: 0,
    terciarizado: false,
    deposito: '',
    cantidadRetirada: 0,
    cantidadAgregada: 0
  });

  useEffect(() => {
    dispatch(getStock());
    dispatch(getStockConfig()); // Cargamos las categorías dinámicas y porcentajes
  }, [dispatch]);

  // --- LÓGICA DE CÁLCULOS ---
  const calcularMetricas = (item) => {
    const consumoPromedioMensual = config?.consumoMensual || 0;
    const factorStockMin = (config?.porcentajeConsumoMensual || 0) / 100;

    const stockMinimo = consumoPromedioMensual * factorStockMin;
    const necesidadProyectada = stockMinimo + consumoPromedioMensual;
    const compraRecomendada = necesidadProyectada - item.enStock;

    return {
      consumoPromedioMensual,
      stockMinimo: stockMinimo.toFixed(2),
      necesidadProyectada: necesidadProyectada.toFixed(2),
      compraRecomendada: compraRecomendada > 0 ? compraRecomendada.toFixed(2) : 0,
      costoUnitario: item.costoUnitario || 0
    };
  };

  const agruparItems = (items) => {
    const grouped = {};
    items.forEach(item => {
      const key = item.descripcion;
      if (!grouped[key]) {
        grouped[key] = {
          descripcion: item.descripcion,
          categoria: item.categoria,
          total: 0,
          items: []
        };
      }
      grouped[key].total += Number(item.enStock);
      grouped[key].items.push(item);
    });
    return Object.values(grouped);
  };

  const toggleRow = (desc) => {
    setOpenRows(prev => ({ ...prev, [desc]: !prev[desc] }));
  };

  const handleOpen = (item = null) => {
    if (item) {
      setFormData({
        id: item._id,
        categoria: item.categoria,
        descripcion: item.descripcion,
        enStock: Number(item.enStock),
        terciarizado: item.terciarizado || false,
        deposito: item.deposito || '',
        cantidadRetirada: 0,
        cantidadAgregada: 0
      });
      setEditMode(true);
    } else {
      setFormData({
        id: '',
        categoria: '',
        descripcion: '',
        enStock: 0,
        terciarizado: false,
        deposito: 'General',
        cantidadRetirada: 0,
        cantidadAgregada: 0
      });
      setEditMode(false);
    }
    setOpen(true);
  };

  const handleClose = () => setOpen(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => {
      let newData = { ...prev };
      if (name === "terciarizado") {
        newData[name] = value === "Si";
        return newData;
      }
      if (name === "cantidadAgregada") {
        newData.cantidadAgregada = value;
        if (value !== "") newData.cantidadRetirada = "";
        return newData;
      }
      if (name === "cantidadRetirada") {
        newData.cantidadRetirada = value;
        if (value !== "") newData.cantidadAgregada = "";
        return newData;
      }
      newData[name] = value;
      return newData;
    });
  };

  const handleSubmit = async () => {
    if (!formData.categoria || !formData.descripcion) return;

    if (editMode) {
      if (formData.cantidadAgregada && formData.cantidadRetirada) {
        alert("Solo podés agregar o retirar stock, no ambos.");
        return;
      }
      await dispatch(putStock(formData.id, { 
        cantidadRetirada: formData.cantidadRetirada, 
        terciarizado: formData.terciarizado, 
        cantidadAgregada: formData.cantidadAgregada 
      }));
    } else {
      await dispatch(postStock(formData));
    }
    await dispatch(getStock());
    handleClose();
  };

  const handleDelete = (id) => {
    if (window.confirm('¿Eliminar este artículo?')) {
      dispatch(deleteStock(id));
    }
  };

  const categoriasDinamicas = config?.categorias || [];

  const normalize = (str) =>
  (str || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");

    const filteredItems = items.filter(item =>
  normalize(item.descripcion).includes(normalize(search))
);

  return (
    <Box sx={{ width: '95%', margin: 'auto', mt: 3 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h4" sx={{ fontFamily: 'InterTight' }}>Inventario Técnico</Typography>
        <TextField
          label="Buscar por descripción..."
          variant="outlined"
          fullWidth
          sx={{ mb: 3, width:"300px" }}
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <Button variant="contained" startIcon={<AddIcon />} onClick={() => handleOpen()}>
          Agregar Stock
        </Button>
      </Box>

      {loading && <CircularProgress sx={{ display: 'block', m: 'auto', mt: 5 }} />}

      {categoriasDinamicas.map((cat) => (
        <TableContainer component={Paper} sx={{ mb: 4, overflowX: "auto" }} key={cat.nombre}>
          <Typography variant="h6" sx={{ p: 2, bgcolor: '#30E691', fontWeight: 'bold', minWidth: 1100 }}>
            {cat.nombre}
          </Typography>
          <Table size="small" sx={{ minWidth: 1100 }}>
            <TableHead>
              <TableRow>
                <TableCell sx={{ width: 220 }}>Descripción</TableCell>
                <TableCell sx={{ width: 120 }} align="center">Stock Actual</TableCell>
                <TableCell sx={{ width: 120 }} align="center">Consumo Mensual</TableCell>
                <TableCell sx={{ width: 120 }} align="center">Stock Mínimo</TableCell>
                <TableCell sx={{ width: 120 }} align="center">Necesidad Proyectada</TableCell>
                <TableCell sx={{ width: 120 }} align="center">Compra Recomendada</TableCell>
                <TableCell sx={{ width: 120 }} align="center">Costo Unitario</TableCell>
                <TableCell sx={{ width: 120 }} align="center">Depósito</TableCell>
                <TableCell sx={{ width: 120 }} align="center">Acciones</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {agruparItems(filteredItems.filter(i => i.categoria === cat.nombre)).map((grupo) => (
                <React.Fragment key={grupo.descripcion}>
                  <TableRow>
                    <TableCell>
                      <IconButton size="small" onClick={() => toggleRow(grupo.descripcion)}>
                        {openRows[grupo.descripcion] ? <KeyboardArrowUpIcon/> : <KeyboardArrowDownIcon/>}
                      </IconButton>
                      {grupo.descripcion}
                    </TableCell>
                    <TableCell  align="center">{grupo.total}</TableCell>
                    <TableCell align="center">-</TableCell>
                    <TableCell align="center">-</TableCell>
                    <TableCell align="center">-</TableCell>
                    <TableCell align="center">-</TableCell>
                    <TableCell align="center">-</TableCell>
                    <TableCell align="center">-</TableCell>
                    <TableCell align="center">-</TableCell>
                  </TableRow>

                  <TableRow>
                    <TableCell colSpan={9} sx={{ p: 0 }}>
                      <Collapse in={openRows[grupo.descripcion]} timeout="auto" unmountOnExit>
                        <Table size="small" sx={{ minWidth: 1100 }}>
                          <TableBody>
                            {grupo.items.map((item) => {
                              const metricas = calcularMetricas(item);
                              return (
                                <TableRow key={item._id}>
                                  <TableCell sx={{ width: 220, pl: 4 }}>{item.descripcion}</TableCell>
                                  <TableCell sx={{ width: 120 }} align="center">{item.enStock}</TableCell>
                                  <TableCell sx={{ width: 120 }} align="center">{metricas.consumoPromedioMensual}</TableCell>
                                  <TableCell sx={{ width: 120 }} align="center">{metricas.stockMinimo}</TableCell>
                                  <TableCell sx={{ width: 120 }} align="center">{metricas.necesidadProyectada}</TableCell>
                                  <TableCell sx={{ width: 120 }} align="center" sx={{ color: metricas.compraRecomendada > 0 ? 'red' : 'inherit', fontWeight: metricas.compraRecomendada > 0 ? 'bold' : 'normal' }}>
                                    {metricas.compraRecomendada}
                                  </TableCell>
                                  <TableCell sx={{ width: 120 }} align="center">U$D {metricas.costoUnitario}</TableCell>
                                  <TableCell sx={{ width: 120 }} align="center">{item.deposito}</TableCell>
                                  <TableCell sx={{ width: 120 }} align="center">
                                    <IconButton onClick={() => handleOpen(item)} color="primary">
                                      <EditIcon />
                                    </IconButton>
                                    <IconButton onClick={() => handleDelete(item._id)} color="error">
                                      <DeleteIcon />
                                    </IconButton>
                                  </TableCell>
                                </TableRow>
                              );
                            })}
                          </TableBody>
                        </Table>
                      </Collapse>
                    </TableCell>
                  </TableRow>
                </React.Fragment>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      ))}

      {/* DIALOGO DINÁMICO */}
      <Dialog open={open} onClose={handleClose} fullWidth maxWidth="sm">
        <DialogTitle>{editMode ? 'Actualizar Stock' : 'Nuevo Ingreso de Stock'}</DialogTitle>
        <DialogContent sx={{ pt: 2, display: 'flex', flexDirection: 'column', gap: 2 }}>

          {!editMode && (
            <>
              <FormControl fullWidth>
                <InputLabel>Categoría</InputLabel>
                <Select
                  name="categoria"
                  value={formData.categoria}
                  label="Categoría"
                  onChange={handleChange}
                >
                  {categoriasDinamicas.map((cat) => (
                    <MenuItem key={cat.nombre} value={cat.nombre}>{cat.nombre}</MenuItem>
                  ))}
                </Select>
              </FormControl>

              <FormControl fullWidth disabled={!formData.categoria}>
                <InputLabel>Descripción</InputLabel>
                <Select
                  name="descripcion"
                  value={formData.descripcion}
                  label="Descripción"
                  onChange={handleChange}
                >
                  {(categoriasDinamicas.find(c => c.nombre === formData.categoria)?.items || []).map((desc) => (
                    <MenuItem key={desc} value={desc}>{desc}</MenuItem>
                  ))}
                </Select>
              </FormControl>

              <FormControl fullWidth>
                <InputLabel>Depósito</InputLabel>
                <Select
                  name="deposito"
                  value={formData.deposito}
                  label="Depósito"
                  onChange={handleChange}
                >
                  <MenuItem value="General">General</MenuItem>
                  <MenuItem value="Nave">Nave</MenuItem>
                  <MenuItem value="Oficina">Oficina</MenuItem>
                </Select>
              </FormControl>

              <TextField
                name="enStock"
                label="Stock Inicial"
                type="number"
                fullWidth
                value={formData.enStock}
                onChange={handleChange}
              />
            </>
          )}

          {editMode && (
            <>
              <Typography variant="subtitle2" color="textSecondary">
                Item: {formData.descripcion} ({formData.deposito})
              </Typography>
              <TextField
                name="cantidadAgregada"
                label="Ingresar Stock"
                type="number"
                fullWidth
                value={formData.cantidadAgregada}
                onChange={handleChange}
                disabled={!!formData.cantidadRetirada}
              />
              <TextField
                name="cantidadRetirada"
                label="Retirar Stock"
                type="number"
                fullWidth
                value={formData.cantidadRetirada}
                onChange={handleChange}
                disabled={!!formData.cantidadAgregada}
              />
            </>
          )}

          <FormControl fullWidth>
            <InputLabel>Terciarizado</InputLabel>
            <Select
              name="terciarizado"
              value={formData.terciarizado ? "Si" : "No"}
              label="Terciarizado"
              onChange={handleChange}
            >
              <MenuItem value="No">No</MenuItem>
              <MenuItem value="Si">Si</MenuItem>
            </Select>
          </FormControl>
