                        }}
                    />
                )}

                {!reservasLeer && (
                    <Tab
                        label="Nueva"
                        sx={{
                            textTransform: "capitalize",
                            fontFamily: "InterTight",
                            fontSize: "17px"
                        }}
                    />
                )}
            </Tabs>

            <TabPanel value={value} index={0}>
