import React, { useEffect, useState } from 'react';
import axios from 'axios';
import {
  Box,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  CircularProgress,
  IconButton,
  useTheme,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Button,
  TextField,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Switch,
  FormControlLabel,
} from '@mui/material';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import { useDispatch, useSelector } from 'react-redux';
import { fetchActiveUsers } from '../../../../../../redux/actions/userActions'; 
import { deactivateUser } from '../../../../../../redux/actions/userActions'; 
import { editUser } from '../../../../../../redux/actions/userActions'; 

//JSX:
export default function UserTable() {
  const theme = useTheme();
  const isLight = theme.palette.mode === 'light';
  const dispatch = useDispatch();
  const { users, loadingUsers, errorUsers } = useSelector(state => state.user);
  const [openModal, setOpenModal] = useState(false);
  const [userToDelete, setUserToDelete] = useState(null);
  const [openEditModal, setOpenEditModal] = useState(false);
  const [userToEdit, setUserToEdit] = useState(null);
  const [editData, setEditData] = useState({
    nombre: '',
    telefono: '',
    rol: '',
    usuarios: false,
    reservas: false,
    tecnica: false,
    blog: false,
    stock: false
  });

  //Función para obtener usuarios activos:
  useEffect(() => {
    dispatch(fetchActiveUsers());
  }, [dispatch]);

  const traducirRol = (rol) => {
    switch (rol) {
      case 'USER_ADMIN':
        return 'Administrador';
      case 'USER_EMPLOYE':
        return 'Usuario';
      default:
        return rol;
    }
  };

  const traducirRolApi = (rolTexto) => {
    return rolTexto === 'Administrador' ? 'USER_ADMIN' : 'USER_EMPLOYE';
  };

  const handleDeleteConfirmation = (userId) => {
    setUserToDelete(userId);
    setOpenModal(true);
  };

  //Función para desactivar usuarios:
  const handleDeleteUser = () => {
    if (userToDelete) {
      dispatch(deactivateUser(userToDelete));
      setOpenModal(false);
    }
  };

  const handleCancelDelete = () => {
    setOpenModal(false);
  };

  const handleEdit = (userId) => {
    const selectedUser = users.find(u => u.uid === userId);
    if (selectedUser) {
      setUserToEdit(userId);
      setEditData({
        nombre: selectedUser.nombre,
        telefono: selectedUser.telefono,
        rol: selectedUser.rol === 'USER_ADMIN' ? 'Administrador' : 'Usuario',
        usuarios: selectedUser.usuarios,
        reservas: selectedUser.reservas,
        tecnica: selectedUser.tecnica,
        blog: selectedUser.blog,
        stock: selectedUser.stock
      });
      setOpenEditModal(true);
    }
  };

  const handleEditChange = (field, value) => {
    setEditData(prev => ({
      ...prev,
      [field]: value,
    }));
  };

  //Función para editar usuarios:
  const handleSaveEdit = () => {
  const payload = {
    nombre: editData.nombre,
    telefono: editData.telefono,
    rol: traducirRolApi(editData.rol),
    usuarios: editData.rol === 'Administrador' ? true : editData.usuarios,
    reservas: editData.rol === 'Administrador' ? true : editData.reservas,
    tecnica: editData.rol === 'Administrador' ? true : editData.tecnica,
    blog: editData.rol === 'Administrador' ? true : editData.blog,
     stock: editData.rol === 'Administrador' ? true : editData.stock,
  };

  dispatch(editUser(userToEdit, payload));
  setOpenEditModal(false);
};

  return (
    <Box sx={{ width: '90%', margin: 'auto', marginTop: 3, marginBottom: 6 }}>
      <Typography variant="h5" gutterBottom sx={{ fontFamily: 'InterTight' }}>
        Listado de usuarios
      </Typography>

      {loadingUsers ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', marginTop: 5 }}>
          <CircularProgress />
          <Typography variant="h6" sx={{ marginLeft: 2 }}>
            Cargando lista de usuarios...
          </Typography>
        </Box>
      ) : (
        <TableContainer component={Paper}>
          <Table>
            <TableHead>
              <TableRow sx={{ backgroundColor: isLight ? '#30E691' : 'inherit' }}>
                {['Nombre completo', 'Teléfono', 'Correo Electrónico', 'Función', 'Gestión'].map((title, idx) => (
                  <TableCell
                    key={idx}
                    sx={{
                      fontWeight: 'bold',
                      fontSize: '1rem',
                      color: isLight ? '#fff' : 'primary.main',
                      py: 2,
                    }}
                  >
                    {title}
                  </TableCell>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {Array.isArray(users) && users.length > 0 ? (
                users.map((user, index) => (
                  <TableRow key={index}>
                    <TableCell>{user.nombre}</TableCell>
                    <TableCell>{user.telefono || 'No disponible'}</TableCell>
                    <TableCell>{user.correo}</TableCell>
                    <TableCell>{traducirRol(user.rol)}</TableCell>
                    <TableCell>
                      <Box sx={{ display: 'flex', gap: 2 }}>
                        <IconButton color="primary" onClick={() => handleEdit(user.uid)}>
                          <EditIcon />
                        </IconButton>
                        <IconButton color="error" onClick={() => handleDeleteConfirmation(user.uid)}>
                          <DeleteIcon />
                        </IconButton>
                      </Box>
                    </TableCell>
                  </TableRow>
                ))
              ) : (
                <TableRow>
                  <TableCell colSpan={5} align="center">
                    No hay usuarios disponibles
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </TableContainer>
      )}

      {/* Modal de confirmación */}
      <Dialog open={openModal} onClose={handleCancelDelete}>
        <DialogTitle>Confirmación de desactivación</DialogTitle>
        <DialogContent>
          <Typography variant="body1">
            ¿Estás seguro de que deseas dar de baja este usuario?
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCancelDelete} color="secondary">
            Cancelar
          </Button>
          <Button onClick={handleDeleteUser} color="error">
            Eliminar
          </Button>
        </DialogActions>
      </Dialog>

      {/* Modal de edición */}
      <Dialog open={openEditModal} onClose={() => setOpenEditModal(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Editar Usuario</DialogTitle>
        <DialogContent sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 2 }}>
          <TextField
            label="Nombre completo"
            value={editData.nombre}
            onChange={(e) => handleEditChange('nombre', e.target.value)}
            fullWidth
          />
          <TextField
            label="Teléfono"
            value={editData.telefono}
            onChange={(e) => handleEditChange('telefono', e.target.value)}
            fullWidth
          />
          <FormControl fullWidth>
            <InputLabel>Rol</InputLabel>
            <Select
              value={editData.rol}
              label="Rol"
              onChange={(e) => handleEditChange('rol', e.target.value)}
            >
              <MenuItem value="Administrador">Administrador</MenuItem>
              <MenuItem value="Usuario">Usuario</MenuItem>
            </Select>
          </FormControl>

          {/* Mostrar switches sólo si el rol es "Usuario" */}
          {editData.rol === 'Usuario' && (
            <>
              <FormControlLabel
                control={<Switch checked={editData.usuarios} onChange={(e) => handleEditChange('usuarios', e.target.checked)} />}
                label="Acceso a Usuarios"
              />
              <FormControlLabel
                control={<Switch checked={editData.reservas} onChange={(e) => handleEditChange('reservas', e.target.checked)} />}
                label="Acceso a Reservas"
              />
              <FormControlLabel
                control={<Switch checked={editData.tecnica} onChange={(e) => handleEditChange('tecnica', e.target.checked)} />}
                label="Acceso a Área Técnica"
              />
              <FormControlLabel
                control={<Switch checked={editData.blog} onChange={(e) => handleEditChange('blog', e.target.checked)} />}
                label="Acceso a Blog"
              />
               <FormControlLabel
                control={<Switch checked={editData.stock} onChange={(e) => handleEditChange('stock', e.target.checked)} />}
                label="Acceso a stock"
              />
            </>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenEditModal(false)} color="secondary">
            Cancelar
          </Button>
          <Button onClick={handleSaveEdit} variant="contained" sx={{ backgroundColor: '#12824c', color: 'white' }}>
            Guardar Cambios
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}

// Importaciones:
import { DemoContainer } from '@mui/x-date-pickers/internals/demo';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import React, { useEffect } from 'react';
import dayjs from 'dayjs';
import 'dayjs/locale/es';
import { FormControl, InputLabel, MenuItem, Select } from '@mui/material';
import { useDispatch, useSelector } from 'react-redux';
import { fetchHorariosDisponibles } from '../../../../../redux/actions/formActions';

// Configuración de idioma para dayjs
dayjs.locale({
    name: 'es-custom',
    months: ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio', 'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'],
    monthsShort: ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'],
    weekdays: dayjs.Ls['es'].weekdays,
    weekdaysShort: dayjs.Ls['es'].weekdaysShort,
    weekdaysMin: dayjs.Ls['es'].weekdaysMin,
    formats: dayjs.Ls['es'].formats,
    ordinal: dayjs.Ls['es'].ordinal,
    weekStart: dayjs.Ls['es'].weekStart,
}, null, true);

dayjs.locale('es-custom');

export default function BasicDatePicker({
    fechaInstalacion,
    setFechaInstalacion,
    franjaHoraria,
    setFranjaHoraria,
    tipoInmueble,
    sinEstilo = false,
    ignorarTipoInmueble = false
}) {
    const dispatch = useDispatch();
    const { horariosDisponibles } = useSelector((state) => state.form);

    // Establecemos el número de días a bloquear según el tipo de inmueble
    const diasBloqueados = ignorarTipoInmueble
        ? 0
        : tipoInmueble === 'edificio'
            ? 5
            : tipoInmueble === 'casa' || tipoInmueble === 'ph'
                ? 3
                : 0;

    const estilos = sinEstilo
        ? {}
        : {
            backgroundColor: "#edeaff",
            borderRadius: "25px",
            '& .MuiOutlinedInput-root': {
                borderRadius: "25px",
                backgroundColor: "#edeaff",
                '& fieldset': {
                    borderColor: '#ccc',
                },
                '&:hover fieldset': {
                    borderColor: '#8048ff',
                },
                '&.Mui-focused fieldset': {
                    borderColor: '#8048ff',
                },
            },
            '& .MuiInputLabel-root': {
                color: '#161616',
            },
            '& .MuiInputLabel-root.Mui-focused': {
                color: '#8048ff',
            },
        };

    // Función para calcular días hábiles
    const calcularDiasHabiles = (fechaInicio, diasAHabilitar) => {
        let diasContados = 0;
        let fecha = dayjs(fechaInicio);

        while (diasContados < diasAHabilitar) {
            fecha = fecha.add(1, 'day');
            if (fecha.day() !== 0 && fecha.day() !== 6) {
                diasContados++;
            }
        }
        return fecha;
    };

    // Función para deshabilitar los días no permitidos
    const shouldDisableDate = (date) => {
        // Solo fines de semana bloqueados si ignoramos tipo de inmueble
        if (ignorarTipoInmueble) {
            return date.day() === 0 || date.day() === 6;
        }

        const today = dayjs();
        const diasHabiles = diasBloqueados;
        const disableFrom = calcularDiasHabiles(today, diasHabiles);

        return date.isBefore(disableFrom, 'day') || date.day() === 0 || date.day() === 6;
    };

    useEffect(() => {
        if (fechaInstalacion) {
            const fechaFormateada = dayjs(fechaInstalacion).format('YYYY-MM-DD');
            dispatch(fetchHorariosDisponibles(fechaFormateada));
        }
    }, [fechaInstalacion, dispatch]);

    const handleDateChange = (newValue) => {
        setFechaInstalacion(newValue);
        setFranjaHoraria("");
        if (newValue) {
            fetchHorariosDisponibles(newValue);
        }
    };

    return (
        <LocalizationProvider dateAdapter={AdapterDayjs}>
            <DemoContainer components={['DatePicker']} sx={{ marginBottom: 2 }}>
                <DatePicker
                    format="DD/MM/YYYY"
                    label="Fecha de instalación"
                    value={fechaInstalacion}
                    onChange={handleDateChange}
                    shouldDisableDate={shouldDisableDate}
                    sx={estilos}
                />
            </DemoContainer>

            {fechaInstalacion && (
                <FormControl
                    fullWidth
                    sx={{
                        mt: 2,
                        ...estilos,
                        width: 260,
                        margin: '0 auto',
                    }}
                    disabled={horariosDisponibles.length === 0}
                >
                    <InputLabel id="horario-label">Horario de instalación</InputLabel>
                    <Select
                        labelId="horario-label"
                        value={franjaHoraria}
                        label="Horario de instalación"
                        onChange={(e) => setFranjaHoraria(e.target.value)}
                    >
                        {horariosDisponibles.length > 0 ? (
                            horariosDisponibles.map((franja) => (
                                <MenuItem key={franja} value={franja}>
                                    {franja}
                                </MenuItem>
                            ))
                        ) : (
                            <MenuItem value="" disabled>
                                No hay horarios disponibles
                            </MenuItem>
                        )}
                    </Select>
                </FormControl>
            )}
        </LocalizationProvider>
    );
}

